-- إنشاء جدولين يمثلان مصفوفتين: A (2x3) و B (3x2)
CREATE TABLE A (row INT, col INT, val INT);
CREATE TABLE B (row INT, col INT, val INT);

-- إدخال بيانات المصفوفة A
INSERT INTO A VALUES (0,0,1),(0,1,2),(0,2,3),(1,0,4),(1,1,5),(1,2,6);

-- إدخال بيانات المصفوفة B
INSERT INTO B VALUES (0,0,7),(0,1,8),(1,0,9),(1,1,10),(2,0,11),(2,1,12);

-- ضرب المصفوفات: الناتج C[i][j] = SUM(A[i][k] * B[k][j])
SELECT A.row, B.col, SUM(A.val * B.val) AS val
FROM A JOIN B ON A.col = B.row
GROUP BY A.row, B.col
ORDER BY A.row, B.col;

