CREATE TABLE files (name TEXT, records INTEGER, rec_size INTEGER, block_size INTEGER);
INSERT INTO files VALUES ('Students', 5000, 100, 1024), ('Orders', 20000, 200, 1024);
-- bfr = floor(حجم الكتلة / حجم السجل) لأن السجل غير المتداخل لا يعبر حدود الكتلة
WITH RECURSIVE b AS (
  SELECT name, block_size / rec_size AS bfr,
         (records + block_size / rec_size - 1) / (block_size / rec_size) AS blocks
  FROM files
),
-- كل خطوة بحث ثنائي تنصّف عدد الكتل المتبقية حتى تبقى كتلة واحدة
s(name, bfr, blocks, n, steps) AS (
  SELECT name, bfr, blocks, blocks, 0 FROM b
  UNION ALL
  SELECT name, bfr, blocks, (n + 1) / 2, steps + 1 FROM s WHERE n > 1
)
SELECT name, bfr, blocks AS heap_worst, steps AS binary_worst
FROM s WHERE n = 1 ORDER BY name;

