CREATE TABLE lock_req (seq INTEGER, tx TEXT, item TEXT, mode TEXT);
INSERT INTO lock_req VALUES
 (1,'T1','A','S'),(2,'T2','A','S'),(3,'T3','A','X'),
 (4,'T2','B','X'),(5,'T1','B','S');
-- القاعدة: نفس العنصر + معاملتان مختلفتان + (أحدهما على الأقل حصري)، والأقدم تسلسلاً يحجب
SELECT b.tx AS waits, a.tx AS blocked_by, a.item, a.mode || b.mode AS modes
FROM lock_req a JOIN lock_req b
  ON a.item = b.item AND a.tx <> b.tx AND a.seq < b.seq
WHERE a.mode = 'X' OR b.mode = 'X'
ORDER BY b.seq, a.seq;

CREATE TABLE wait_for (waiter TEXT, holder TEXT);
-- T1 تنتظر T2 وT2 تنتظر T3 وT3 تنتظر T1: دورة. أما T4 فتنتظر فقط
INSERT INTO wait_for VALUES ('T1','T2'),('T2','T3'),('T3','T1'),('T4','T1');
WITH RECURSIVE walk(start, cur, path) AS (
  SELECT waiter, holder, waiter || '>' || holder FROM wait_for
  UNION ALL
  SELECT w.start, f.holder, w.path || '>' || f.holder
  FROM walk w JOIN wait_for f ON f.waiter = w.cur
  -- نتوقف عند العودة إلى نقطة البداية، ونمنع تكرار عقدة أخرى كي لا نحلّق للأبد
  WHERE w.cur <> w.start
    AND (instr('>' || w.path || '>', '>' || f.holder || '>') = 0 OR f.holder = w.start)
)
SELECT start AS in_deadlock, path FROM walk WHERE cur = start ORDER BY start;

CREATE TABLE log (lsn INTEGER, tx TEXT, item TEXT, bfim INTEGER, afim INTEGER);
INSERT INTO log VALUES
 (1,'T1','A',10,20),(2,'T2','B',5,9),(3,'T3','A',20,35),
 (4,'T3','C',7,8),(5,'T2','B',9,12);
CREATE TABLE committed (tx TEXT);
INSERT INTO committed VALUES ('T1'),('T3');
-- حالة القرص لحظة الانهيار: كُتبت صفحة B غير المثبّتة (steal)، وضاع تعديل C المثبّت (no-force)
CREATE TABLE disk (item TEXT, value INTEGER);
INSERT INTO disk VALUES ('A',20),('B',12),('C',7);
-- redo: afim لآخر كتابة مثبّتة. undo: bfim لأقدم كتابة غير مثبّتة جاءت بعدها
WITH lc AS (
  SELECT item, MAX(lsn) AS lsn FROM log
  WHERE tx IN (SELECT tx FROM committed) GROUP BY item
)
SELECT d.item, d.value AS on_disk,
  COALESCE(
    (SELECT l.bfim FROM log l
      WHERE l.item = d.item AND l.tx NOT IN (SELECT tx FROM committed)
        AND l.lsn > COALESCE((SELECT lsn FROM lc WHERE lc.item = d.item), 0)
      ORDER BY l.lsn LIMIT 1),
    (SELECT l.afim FROM log l WHERE l.item = d.item AND l.lsn =
      (SELECT lsn FROM lc WHERE lc.item = d.item))
  ) AS recovered
FROM disk d ORDER BY d.item;

