-- الخاصية البسيطة: قراءة إن كان التصريح >= التصنيف. خاصية النجمة: كتابة إن كان التصريح <= التصنيف
SELECT u.name, d.title,
  CASE WHEN u.clearance >= d.level THEN 'R' ELSE '-' END AS read,
  CASE WHEN u.clearance <= d.level THEN 'W' ELSE '-' END AS write
FROM users u CROSS JOIN docs d
ORDER BY u.name DESC, d.level;

