CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT, qty INTEGER, reorder_level INTEGER);
CREATE TABLE reorder_log (product TEXT, qty_left INTEGER);
INSERT INTO products VALUES (1,'Pen',50,20),(2,'Paper',30,25),(3,'Stapler',12,5);
-- الحدث: تحديث الكمية / الشرط: WHEN / الإجراء: الإدخال في السجل
CREATE TRIGGER low_stock AFTER UPDATE OF qty ON products
FOR EACH ROW WHEN NEW.qty < NEW.reorder_level
BEGIN
  INSERT INTO reorder_log VALUES (NEW.name, NEW.qty);
END;
-- تحديث واحد يمسّ ثلاثة صفوف: يُنفَّذ المشغّل لكل صف على حدة
UPDATE products SET qty = qty - 10;
SELECT product, qty_left FROM reorder_log ORDER BY product;

