-- حِمل كل مركز في كل أسبوع = كمية الأمر × زمن الوحدة، ثم نقارنه بالسعة الأسبوعية
SELECT r.work_center, p.week,
       SUM(p.qty * r.min_per_unit) AS load_min, w.cap_min,
       SUM(p.qty * r.min_per_unit) * 100 / w.cap_min AS util_pct,
       CASE WHEN SUM(p.qty * r.min_per_unit) > w.cap_min THEN 'OVERLOAD' ELSE 'ok' END AS status,
       SUM(p.qty * r.min_per_unit) * w.cost_per_min AS cost
FROM planned_orders p
JOIN routing r ON r.item = p.item
JOIN work_center w ON w.name = r.work_center
GROUP BY r.work_center, p.week
ORDER BY r.work_center, p.week;

