-- العملية أفقية: نحدّد مرحلة كل طلب من آخر وثيقة وُلدت له في أي قسم
-- (LEFT JOIN يُبقي الطلب الذي لم يصل بعد إلى القسم التالي)
SELECT o.id, o.customer,
       CASE WHEN p.pay_date IS NOT NULL THEN 'paid'
            WHEN i.inv_date IS NOT NULL THEN 'invoiced'
            WHEN s.ship_date IS NOT NULL THEN 'shipped'
            ELSE 'ordered' END AS stage,
       CASE WHEN p.pay_date IS NOT NULL THEN 'done'
            WHEN i.inv_date IS NOT NULL THEN 'customer'
            WHEN s.ship_date IS NOT NULL THEN 'Finance'
            ELSE 'Warehouse' END AS waiting_on,
       COALESCE(CAST(julianday(s.ship_date) - julianday(o.order_date) AS INTEGER), '-') AS days_to_ship,
       COALESCE(CAST(julianday(p.pay_date) - julianday(o.order_date) AS INTEGER), '-') AS days_to_cash
FROM sales_orders o
LEFT JOIN shipments s ON s.order_id = o.id
LEFT JOIN invoices i ON i.order_id = o.id
LEFT JOIN payments p ON p.order_id = o.id
ORDER BY o.id;
